const RESMI_META={"TUR": {"ders": "Türkçe", "kaynak": "https://tymm.meb.gov.tr/ogretim-programlari/ders/ortaokul-turkce-dersi"}, "MAT": {"ders": "Matematik", "kaynak": "https://tymm.meb.gov.tr/ogretim-programlari/ders/ortaokul-matematik-dersi"}, "FEN": {"ders": "Fen Bilimleri", "kaynak": "https://tymm.meb.gov.tr/ogretim-programlari/ders/fen-bilimleri-dersi"}, "SOS": {"ders": "Sosyal Bilgiler", "kaynak": "https://tymm.meb.gov.tr/ogretim-programlari/ders/sosyal-bilgiler-dersi"}, "ING": {"ders": "İngilizce", "kaynak": "https://tymm.meb.gov.tr/ogretim-programlari/ders/coklu-yabanci-dil-egitim-modeli-ingilizce"}};
const UNIT_WORD={MAT:'Tema',TUR:'Tema',ING:'Tema',SOS:'Öğrenme Alanı',FEN:'Ünite'};
const unitLbl=k=>`${k.unit}. ${UNIT_WORD[k.course]||'Ünite'}: ${k.unitName}`;
/* ---------- Resmi öğretim programı görünümü (öğretmen, veli) ---------- */
const RCOURSE={TUR:'Türkçe',MAT:'Matematik',FEN:'Fen Bilimleri',SOS:'Sosyal Bilgiler',ING:'İngilizce'};
function rsState(def){UI.rp=UI.rp||{c:def.c||'MAT',g:def.g||7,q:'',open:{}};return UI.rp}
function resmiView(def={}){const R=rsState(def);const grades=def.grades||[5,6,7,8];const courses=def.courses||Object.keys(RCOURSE);if(!grades.includes(+R.g))R.g=grades[0];if(!courses.includes(R.c))R.c=courses[0];
  const G=RESMI[R.c][R.g];const q=((UI.q||{}).rsq||'').toLocaleLowerCase('tr');const kzUse={};KZ.forEach(k=>{if(k.course===R.c&&k.grade===+R.g)(kzUse[k.code]=kzUse[k.code]||[]).push(k.topic)});
  const seen=new Set();let total=0,shown=0;
  const units=G.u.map(u=>{const cs=u.c.filter(c=>{const dup=R.c==='TUR'&&seen.has(c[0]);seen.add(c[0]);total+=dup?0:1;return !dup}).filter(c=>!q||((c[1]||'')+' '+c[2].map(a=>a[1]||'').join(' ')).toLocaleLowerCase('tr').includes(q));shown+=cs.length;if(q&&!cs.length)return '';
    const rep=R.c==='TUR'?u.c.length:null;const key=R.c+R.g+'-'+u.no;const open=q?true:!!R.open[key];
    return `<section class="rs-u ${open?'open':''}"><button class="rs-uh" data-act="rsTog" data-v="${key}" aria-expanded="${open}">${ic(open?'cd':'cr',15)}<span class="rs-un">${u.no}. ${UNIT_WORD[R.c]}</span><b class="sp">${esc(u.ad)}</b>${u.saat?`<span class="meta">${u.saat} ders saati</span>`:''}${R.c==='ING'?'':`<span class="pill p-krem">${cs.length} kazanım</span>`}</button>
     ${open?`<div class="rs-ub">${u.kapsam?`<p class="small" style="margin:0 0 8px"><b>Tema kapsamı:</b> <i>${esc([].concat(u.kapsam).join(' '))}</i></p>`:''}${R.c==='ING'?'':cs.map(c=>`<div class="rs-c"><div class="row" style="align-items:flex-start;flex-wrap:nowrap"><div class="sp"><b class="small">${c[1]?esc(c[1]):'<span class="muted">Çıktı metni alınamadı (resmi sayfada okunabilir)</span>'}</b>${(kzUse[c[0]]||[]).length?`<div class="row" style="gap:4px;margin-top:4px">${kzUse[c[0]].map(t=>`<span class="pill p-soft">${ic('target',11)} Sistemde: ${esc(t)}</span>`).join('')}</div>`:''}
       ${c[2].length&&c[2].some(a=>a[1])?`<ol class="rs-alt">${c[2].map(a=>`<li><b>${a[0]})</b> ${esc(a[1]||'')}</li>`).join('')}</ol>`:c[2].length?`<div class="meta">${c[2].length} süreç bileşeni</div>`:''}</div></div></div>`).join('')||'<div class="meta">Aramayla eşleşen çıktı yok.</div>'}<a class="lnk small" href="${u.url}" target="_blank" rel="noopener">${ic('dl',12)} Resmi sayfada aç</a></div>`:''}</section>`}).join('');
  return `<section class="${def.cls||'card panel'}"><div class="row" style="gap:10px;align-items:flex-end;flex-wrap:wrap"><div class="seg">${courses.map(c=>`<button class="${R.c===c?'on':''}" data-act="rsSet" data-k="c" data-v="${c}">${RCOURSE[c]}</button>`).join('')}</div>${grades.length>1?`<div class="seg">${grades.map(g=>`<button class="${+R.g===g?'on':''}" data-act="rsSet" data-k="g" data-v="${g}">${g}. sınıf</button>`).join('')}</div>`:''}<input class="in" style="max-width:260px;min-height:36px" data-q="rsq" value="${esc((UI.q||{}).rsq||'')}" placeholder="Kazanımlarda ara (ör. orantı)" aria-label="Öğrenme çıktısı ara"><span class="sp"></span><button class="btn sm sec" data-act="rsAll">${ic('layers',14)} ${Object.values(R.open).filter(Boolean).length?'Tümünü kapat':'Tümünü aç'}</button></div>
   <div class="rs-src">${ic('shield',14)} <span><b>Kaynak:</b> MEB Türkiye Yüzyılı Maarif Modeli öğretim programı · <a class="lnk" href="${RESMI_META[R.c].kaynak}" target="_blank" rel="noopener">tymm.meb.gov.tr</a>${G.not?` · ${esc(G.not)}`:''} · ${G.u.length} ${UNIT_WORD[R.c].toLocaleLowerCase('tr')} · ${R.c==='ING'?'tema kapsamları':total+' kazanım'}${q?` · ${shown} eşleşme`:''}</span></div>
   ${R.c==='ING'?`<div class="rs-warn">${ic('info',14)} İngilizce için tema kapsamları resmi sayfadan alındı; çıktı metinleri alınamadı. Program PDF’i eklendiğinde metinler tamamlanır.</div>`:''}
   <div class="rs-list">${units}</div></section>`}
